// Route: POST /{{action:#}}
public function store(Request $request)
{
    $request->validate([
        '{{name:file}}' => 'required|file|max:10240',
    ]);

    $path = $request->file('{{name:file}}')
        ->store('uploads', 'public');

    return response()->json(['path' => $path], 201);
}

