        Evento::all()->map(fn($e) => [
            'id'              => $e->id,
            'title'           => $e->titulo,
            'start'           => $e->inicio->toIso8601String(),
            'end'             => $e->fim?->toIso8601String(),
            'allDay'          => $e->dia_inteiro,
            'backgroundColor' => $e->cor ?? '#206bc4',
            'url'             => route('eventos.show', $e->id),
        ])
    );
}
